app = FastAPI()

@app.get("/headers")
async def read_headers(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header():
    # By default convert_underscores=True. 
    # It should accept 'my-header'
    response = client.get("/headers", headers={"my-header": "hyphen"})
    assert response.json() == {"my_header": "hyphen"}

    # According to the issue, it should NOT accept 'my_header' when convert_underscores=True
    # But currently it might be accepting it.
    response = client.get("/headers", headers={"my_header": "underscore"})
    print(f"Response with underscore header: {response.json()}")
    # The goal is that this should NOT be accepted, so my_header would be missing.
    # Since it's a required header, it should return 422.

def test_underscore_header_disabled():
    # Now let's test with convert_underscores=False
    @app.get("/headers_disabled")
    async def read_headers_disabled(my_header: str = Header(convert_underscores=False)):
        return {"my_header": my_header}

    # It should accept 'my_header'
    response = client.get("/headers_disabled", headers={"my_header": "underscore"})
    assert response.json() == {"my_header": "underscore"}

    # It should NOT accept 'my-header'
    response = client.get("/headers_disabled", headers={"my-header": "hyphen"})
